CREATE TABLE CPF_RUNTIME_INSTANCE_HEALTH (SYSTEM_ID VARCHAR2(64) NOT NULL, INSTANCE_ID VARCHAR2(128) NOT NULL, VERSION VARCHAR2(64), BUILD_SHA VARCHAR2(64), STARTED_AT TIMESTAMP WITH TIME ZONE NOT NULL, UPTIME_MS NUMBER(19) NOT NULL, LAST_SEEN_AT TIMESTAMP WITH TIME ZONE NOT NULL, LIVENESS VARCHAR2(32) NOT NULL, READINESS VARCHAR2(32) NOT NULL, STARTUP VARCHAR2(32) NOT NULL, DRAINING NUMBER(1) DEFAULT 0 NOT NULL, MAINTENANCE NUMBER(1) DEFAULT 0 NOT NULL, PAYLOAD_JSON CLOB NOT NULL, CONSTRAINT PK_CPF_RIH PRIMARY KEY(SYSTEM_ID,INSTANCE_ID));
CREATE INDEX IX_CPF_RIH_LAST_SEEN ON CPF_RUNTIME_INSTANCE_HEALTH(LAST_SEEN_AT);
CREATE INDEX IX_CPF_RIH_READINESS ON CPF_RUNTIME_INSTANCE_HEALTH(READINESS,LAST_SEEN_AT);
